use crate::*;
use super::{policy,plan::{Resource,Patch},state};
pub fn hardware()->Value{
 let cores=std::thread::available_parallelism().map(|n|n.get()).unwrap_or(1);let mut data=json!({"logicalCores":cores,"cpu":null,"memoryMb":null,"gpus":[],"note":"硬件信息仅在本地读取；不承诺 FPS 提升。"});
 #[cfg(target_arch="x86_64")]{use std::arch::x86_64::__cpuid;if __cpuid(0x80000000).eax>=0x80000004{let mut bytes=Vec::new();for leaf in 0x80000002..=0x80000004{let c=__cpuid(leaf);for v in [c.eax,c.ebx,c.ecx,c.edx]{bytes.extend(v.to_le_bytes());}}data["cpu"]=json!(String::from_utf8_lossy(&bytes).trim_matches('\0').trim());}}
 #[cfg(windows)]unsafe{use windows_sys::Win32::System::SystemInformation::{GlobalMemoryStatusEx,MEMORYSTATUSEX};let mut mem:MEMORYSTATUSEX=std::mem::zeroed();mem.dwLength=std::mem::size_of::<MEMORYSTATUSEX>() as u32;if GlobalMemoryStatusEx(&mut mem)!=0{data["memoryMb"]=json!(mem.ullTotalPhys/1048576);}
  use windows::Win32::Graphics::Dxgi::{CreateDXGIFactory1,IDXGIFactory1};let mut gpus=Vec::new();if let Ok(factory)=CreateDXGIFactory1::<IDXGIFactory1>(){for index in 0..8{let Ok(adapter)=factory.EnumAdapters1(index)else{break};if let Ok(desc)=adapter.GetDesc1(){if desc.Flags&2!=0{continue;}let n=desc.Description.iter().position(|c|*c==0).unwrap_or(desc.Description.len());gpus.push(json!({"name":String::from_utf16_lossy(&desc.Description[..n]),"vramMb":desc.DedicatedVideoMemory/1048576}));}}}data["gpus"]=json!(gpus);
 }data
}
pub fn disk_free(root:&Path)->Option<u64>{
 #[cfg(windows)]{use std::os::windows::ffi::OsStrExt;let path:Vec<u16>=root.as_os_str().encode_wide().chain(Some(0)).collect();let mut available=0;unsafe{if windows_sys::Win32::Storage::FileSystem::GetDiskFreeSpaceExW(path.as_ptr(),&mut available,std::ptr::null_mut(),std::ptr::null_mut())!=0{return Some(available);}}None}
 #[cfg(not(windows))]{let _=root;None}
}
pub fn table()->Result<Value>{let value:Value=serde_json::from_str(include_str!("../../../config/performance-mods.json")).map_err(err)?;if value["version"]!=1||!value["candidates"].is_array(){return Err("性能模组表无效".into());}Ok(value)}
pub fn preset(name:&str,physical:Option<u64>)->Result<Value>{let(memory,render,fps)=match name{"low"=>(2048,6,60),"balanced"=>(4096,10,144),"high"=>(8192,16,144),_=>return Err("请选择低配、均衡或高配预设".into())};let cap=physical.map(|n|n/2).unwrap_or(8192).clamp(512,65536);Ok(json!({"memoryMb":memory.min(cap),"options":{"renderDistance":render,"simulationDistance":render.min(8),"maxFps":fps}}))}
pub async fn analyze(core:&Core,id:&str,args:&Value)->Result<Value>{let root=core.instance(id)?;let cfg=read_json(&policy::under(&root,"kxl.json")?)?;let hardware=hardware();let preset=preset(args["preset"].as_str().unwrap_or("balanced"),hardware["memoryMb"].as_u64())?;let rows=resources::list(core,&json!({"id":id,"kind":"mods"}))?;let ids=rows.as_array().into_iter().flatten().flat_map(|r|r["modIds"].as_array().into_iter().flatten()).filter_map(Value::as_str).map(str::to_owned).collect::<std::collections::HashSet<_>>();let mut warnings=Vec::new();if ids.contains("optifine")&&ids.contains("sodium"){warnings.push("检测到 OptiFine 与 Sodium，请先核对兼容性；工坊不会自动移除模组。".to_owned());}let table=table()?;for item in table["highCost"].as_array().into_iter().flatten(){if item["modId"].as_str().is_some_and(|id|ids.contains(id)){warnings.push(item["note"].as_str().unwrap_or("").to_owned());}}
 let mut mods=Vec::new();let mut download_bytes=0u64;if args["installMods"]==true{for item in table["candidates"].as_array().into_iter().flatten(){if !item["loaders"].as_array().is_some_and(|a|a.iter().any(|v|v==&cfg["loader"]))||item["modId"].as_str().is_some_and(|id|ids.contains(id))||item["incompatible"].as_array().into_iter().flatten().filter_map(Value::as_str).any(|id|ids.contains(id)){continue;}let query=string(item,"query")?;match engine::project_version(core,query,string(&cfg,"version")?,string(&cfg,"loader")?,"mods").await{Ok(v)=>{download_bytes=download_bytes.saturating_add(v["files"][0]["size"].as_u64().unwrap_or(0));mods.push(Resource{source:"modrinth".into(),project_id:string(&v,"project_id")?.into(),version_id:string(&v,"id")?.into(),name:query.into(),side:"both".into(),reason:"本地性能表中的兼容候选".into(),required:true})},Err(_)=>warnings.push(format!("{query} 没有查到当前实例的兼容版本，已跳过。"))}}}
 let options=std::fs::read_to_string(policy::under(&root,"options.txt")?).unwrap_or_default();let current:std::collections::BTreeMap<_,_>=options.lines().filter_map(|s|s.split_once(':')).filter(|(k,_)|["renderDistance","simulationDistance","maxFps"].contains(k)).map(|(k,v)|(k.to_owned(),v.to_owned())).collect();let proposal=json!({"preset":args["preset"].as_str().unwrap_or("balanced"),"memoryMb":preset["memoryMb"],"options":preset["options"],"mods":mods,"estimatedDownloadBytes":download_bytes});Ok(json!({"hardware":hardware,"current":{"memoryMb":cfg["settings"]["memory"],"options":current,"modCount":rows.as_array().map(|a|a.len()).unwrap_or(0),"shaderCount":std::fs::read_dir(root.join("shaderpacks")).into_iter().flatten().flatten().count()},"proposal":proposal,"performanceHash":super::update::digest(&proposal),"warnings":warnings,"note":"只报告实际修改和启动耗时，不承诺 FPS 提升。"}))}
pub async fn apply(core:&Core,task:&mut state::Task,args:&Value,account:&str,settings:&Value)->Result<Value>{if account.is_empty(){return Err("请选择账号后再应用需要启动验证的性能方案。".into());}super::verify::ensure_idle()?;let preview=analyze(core,&task.instance_id,args).await?;if preview["performanceHash"]!=string(args,"performanceHash")?{return Err("性能建议已改变，请重新查看并确认。".into());}let root=core.instance(&task.instance_id)?;let sid=super::snapshot::create(core,&task.instance_id)?;task.snapshots.push(sid.clone());state::save(core,task,"state")?;let before=preview["current"].clone();let result=async{let proposal=&preview["proposal"];let mods:Vec<Resource>=serde_json::from_value(proposal["mods"].clone()).map_err(err)?;let cfg=read_json(&root.join("kxl.json"))?;for r in &mods{super::plan::resource(core,r,string(&cfg,"version")?,string(&cfg,"loader")?,"mods").await?;resource_dependencies::install(core,&super::tools::payload(&task.instance_id,r,"mods")).await?;}if !mods.is_empty()&&std::fs::read_dir(root.join("mods")).into_iter().flatten().flatten().filter(|e|e.path().extension().is_some_and(|s|s=="jar")).count()>80{return Err("优化模组及前置超过 80 个预算，已停止。".into());}let mut cfg=cfg;cfg["settings"]["memory"]=proposal["memoryMb"].clone();write_json(&root.join("kxl.json"),&cfg)?;let set=serde_json::from_value(proposal["options"].clone()).map_err(err)?;super::config_patch::apply(&root,&Patch{file:"options.txt".into(),format:"properties".into(),set})?;if account.is_empty(){return Err("请选择账号后再应用需要启动验证的性能方案。".into());}let start=std::time::Instant::now();let report=super::verify::run(core,&task.instance_id,account,settings).await?;Ok(json!({"applied":true,"before":before,"after":proposal,"startupMs":start.elapsed().as_millis(),"report":report,"rollbackSnapshotId":sid,"note":"未测量 FPS；不承诺帧率提升。"}))}.await;if result.is_err(){super::snapshot::restore(core,&task.instance_id,&sid)?;}result}
#[cfg(test)]mod tests{use super::*;#[test]fn presets_respect_physical_memory_and_table_has_queries(){assert_eq!(preset("high",Some(4096)).unwrap()["memoryMb"],2048);assert_eq!(preset("low",Some(1024)).unwrap()["memoryMb"],512);assert!(preset("system-tweak",None).is_err());let t=table().unwrap();for item in t["candidates"].as_array().unwrap(){assert!(item["query"].is_string());assert!(item["projectId"].is_null());}}}
